import { Component, OnDestroy, TemplateRef, ViewChild } from '@angular/core';

import { ProactiveDefenseIgnoreItem } from '@imunify360-api/proactive-defense';

import { NotificationsService } from 'app/services/notifications';
import { ProactiveDefenseService } from 'app/services/proactive-defense';
import { useLoader } from 'app/utils/loader/decorators';
import { LoaderDirective } from 'app/utils/loader/loader.directive';
import { ModalService } from 'app/utils/modals/modal.service';
import { RequestDirective } from 'app/utils/table/request/request.directive';
import { finalize, Subject, takeUntil } from 'rxjs';
import { FileViewerService } from 'app/utils/file-viewer/file-viewer.service';
import { NAVBAR_TABS } from 'app/components/nav-root/navbar-items.enum';
import { PROACTIVE_DEFENCE_TABS } from '../proactive-defence-tabs.enum';
import { ProactiveDefenseActions } from '../proactive-defense-actions.enum';
import { getSubTabItemsConfig, isActionAllowed } from 'app/utils/allowed-items.utils';


@Component({
    selector: 'i360-proactive-defense-ignore-list',
    templateUrl: './ignore-list.component.html',
})
export class ProactiveDefenseIgnoreListComponent implements OnDestroy {
    @ViewChild(LoaderDirective, {static: true}) loader!: LoaderDirective;
    @ViewChild(RequestDirective, {static: true}) request: RequestDirective;
    @ViewChild('removeModal', {static: true}) public removeModal: TemplateRef<any>;

    ProactiveDefenseActions = ProactiveDefenseActions;
    tabConfig: ISubTabItemsConfig;

    private destroy$ = new Subject<void>();

    constructor(public proactiveDefenseService: ProactiveDefenseService,
                private modalService: ModalService,
                private fileViewerService: FileViewerService,
                private notifications: NotificationsService,
                ) {
        this.tabConfig = getSubTabItemsConfig(NAVBAR_TABS.ProactiveDefense, PROACTIVE_DEFENCE_TABS.IgnoreList);
    }

    ngOnDestroy(): void {
        this.destroy$.next();
    }

    isActionAllowed(actionName: ProactiveDefenseActions): boolean {
        return isActionAllowed(this.tabConfig, actionName);
    }

    async deletePaths(items: ProactiveDefenseIgnoreItem[]) {
        const action = 'proactive-remove-from-ignore';
        const paths = items.map(item => item.path);
        if (await this.modalService.confirm(action, paths)) {
            this.performDeletePaths(paths, items, action);
        }
    }

    private performDeletePaths(paths: string[], items: ProactiveDefenseIgnoreItem[], action: string): void {
        this.loader.show(action);
        this.proactiveDefenseService.ignoreDeletePaths({paths})
            .pipe(
                takeUntil(this.destroy$),
                finalize(() => {
                    this.loader.hide(action);
                }),
            ).subscribe(() => {
                this.notifications.success(
                    'pd.ignoreList.notifications.successfullyRemoved',
                    null,
                    {count: items.length},
                );
                this.request.load();
            });
    }

    async deleteRule(item: ProactiveDefenseIgnoreItem, rule: {id: number, name: string}) {
        if (!await this.modalService.open(this.removeModal, {data: {item, rule}})) {
            return;
        }

        this.performDeleteRule(item, rule);
    }

    private performDeleteRule(item: ProactiveDefenseIgnoreItem, rule: {id: number, name: string}): void {
        this.loader.show('deleteRule');
        this.proactiveDefenseService.ignoreDeleteRule({path: item.path, id: rule.id})
            .pipe(
                takeUntil(this.destroy$),
                finalize(() => {
                    this.loader.hide('deleteRule');
                }),
        ).subscribe(() => {
            this.notifications.success(
                'pd.ignoreList.notifications.successfullyRemoved',
                null,
                {count: 1},
            );
            this.request.load();
        });
    }

    @useLoader
    async viewFile(item: ProactiveDefenseIgnoreItem) {
        await this.fileViewerService.openFileViewer(item.path);
    }
}
